CREATE TABLE src_srm.srm_asn(id BIGINT AUTO_INCREMENT PRIMARY KEY,asn_no VARCHAR(32) UNIQUE,purchase_order_no VARCHAR(32),supplier_code VARCHAR(32),material_code VARCHAR(32),batch_no VARCHAR(64),ship_qty DECIMAL(18,4),ship_date DATE,expected_arrival_date DATE,status VARCHAR(20) DEFAULT 'DRAFT',created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE src_srm.srm_supplier_quality(id BIGINT AUTO_INCREMENT PRIMARY KEY,issue_no VARCHAR(32) UNIQUE,supplier_code VARCHAR(32),source_no VARCHAR(32),defect_qty DECIMAL(18,4),ppm DECIMAL(18,2),problem_desc VARCHAR(500),eight_d_status VARCHAR(20) DEFAULT 'OPEN',due_date DATE,closed_at DATETIME(3));
CREATE TABLE src_srm.srm_supplier_performance(id BIGINT AUTO_INCREMENT PRIMARY KEY,supplier_code VARCHAR(32),period_code VARCHAR(8),delivery_rate DECIMAL(8,2),qualified_rate DECIMAL(8,2),ppm DECIMAL(18,2),score DECIMAL(8,2),rating VARCHAR(8),UNIQUE KEY uk_supplier_period(supplier_code,period_code));
